"""PLINK arm on the exact 37566-site BED generated by the reviewed pilot."""
from pathlib import Path
import datetime,hashlib,json,subprocess,sys,time
HERE=Path(__file__).resolve().parent
PROGRAM=HERE.parents[1]/'dt_research_p5_20260924/tooling/plink'
EXPECTED='47ec461f1768cce1529e226654329268eacd9ca96ee62db4558fa04c4c3d51e4'
OPTIONS=['--allow-extra-chr','--keep-allele-order','--threads','2','--memory','3500','--pca','14','header','tabs','--make-rel','square','--missing','--freqx']
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 root=Path(sys.argv[1]).resolve()
 r=json.loads((root/'RUN_RECEIPT.json').read_text())
 assert r['status'] in ('COMPLETED_PENDING_ROOT_SCIENTIFIC_AUDIT','PARTIAL_PENDING_ROOT_SCIENTIFIC_AUDIT') and r['selected_sites']==37566 and len(r['samples'])==14
 assert sha(PROGRAM)==EXPECTED
 inputs={n:sha(root/n) for n in ['paired.bed','paired.bim','paired.fam']}
 expected={x['path']:x['sha256'] for x in r['output_files']}
 assert all(h==expected[n] for n,h in inputs.items())
 out=root/'A_PLINK';out.mkdir(exist_ok=False)
 command=[str(PROGRAM),*OPTIONS,'--bfile',str(root/'paired'),'--out',str(out/'pca')]
 record={'started_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'command':command,'binary_sha256':EXPECTED,'input_hashes_before':inputs,'runner_sha256':sha(Path(__file__)),'source_pilot_receipt_sha256':sha(root/'RUN_RECEIPT.json'),'status':'RUNNING','no_new_site_or_sample_filter':True}
 t=time.monotonic()
 try:
  with (out/'stdout.log').open('x') as log:
   p=subprocess.run(command,stdout=log,stderr=subprocess.STDOUT)
  record['exit_code']=p.returncode;p.check_returncode()
  record['input_hashes_after']={n:sha(root/n) for n in inputs}
  assert record['input_hashes_after']==inputs
  lines=(out/'pca.eigenvec').read_text().splitlines()
  assert len(lines)==15 and [x.split()[1] for x in lines[1:]]==r['samples']
  assert len((out/'pca.eigenval').read_text().splitlines())==14
  assert '37566 variants and 14 people pass filters and QC.' in (out/'pca.log').read_text()
  record['status']='COMPLETED_PENDING_INDEPENDENT_AUDIT'
 except Exception as error:
  record['status']='FAILED';record['error']=str(error);raise
 finally:
  record['seconds']=time.monotonic()-t
  record['outputs']=[{'path':p.name,'sha256':sha(p),'bytes':p.stat().st_size} for p in sorted(out.iterdir()) if p.is_file()]
  (out/'RECEIPT.json').write_text(json.dumps(record,indent=2,allow_nan=False)+'\n')
 print(json.dumps(record))
if __name__=='__main__':main()
